// x = lon * cos(32°) * SCALE + xOffset, y = -lat * SCALE + yOffset
// SCALE ≈ 6.6296, xOffset ≈ 8, yOffset ≈ 271.19（viewBox「0 0 760 279」に対して）

const WORLD_ROUTE_POINTS = [
  { key: "changan", label: "長安（起点）", x: 733.03, y: 122.48, labelDy: 16 },
  { key: "dunhuang", label: "敦煌", x: 644.5, y: 80.07, labelDy: -10 },
  { key: "kashgar", label: "カシュガル", x: 528.73, y: 84.98, labelDy: 16 },
  { key: "samarkand", label: "サマルカンド", x: 472.75, y: 83.64, labelDy: -10 },
  { key: "merv", label: "メルヴ", x: 440.95, y: 98.22, labelDy: 16 },
  { key: "baghdad", label: "バグダッド", x: 332.67, y: 129.98, labelDy: 16 },
  { key: "antioch", label: "アンティオキア", x: 281.79, y: 108.89, labelDy: -10 },
  { key: "constantinople", label: "コンスタンティノープル", x: 237.27, y: 73.74, labelDy: -10 },
  { key: "rome", label: "ローマ", x: 135.08, y: 67.2, labelDy: 16 },
];

const WORLD_SEA_LABELS = [
  { label: "地中海", x: 169.2, y: 117.66 },
  { label: "黒海", x: 268.4, y: 59.18 },
  { label: "カスピ海", x: 373.8, y: 66.49 },
  { label: "ペルシア湾", x: 373.8, y: 176.15 },
  { label: "紅海", x: 293.2, y: 227.33 },
];

function WorldRouteMap() {
  return (
    <div style={{ backgroundColor: "#FBF8F0", border: "1px solid #DCD3B8", padding: 16, marginBottom: 28 }}>
      <p style={{ fontSize: 11.5, color: COLORS.inkSoft, marginBottom: 10 }}>
        実際の海岸線をもとにした、ローマまでの位置関係図です。シルクロードは中国国内だけの道ではなく、中央アジアの
        オアシス都市やペルシア（中東）を経て、地中海世界のローマにまで達していました。
      </p>
      <svg viewBox="0 0 760 279" style={{ width: "100%", maxHeight: 320, display: "block", margin: "0 auto" }}>
        <path d={WORLD_OUTLINE} fill="#DCD3B8" stroke={COLORS.mist} strokeWidth="1" strokeLinejoin="round" />

        {WORLD_SEA_LABELS.map((s, i) => (
          <text
            key={`sea-${i}`}
            x={s.x}
            y={s.y}
            textAnchor="middle"
            style={{ fontFamily: "'Noto Serif SC', serif", fontSize: 9, fill: COLORS.jade, opacity: 0.75 }}
          >
            {s.label}
          </text>
        ))}

        <polyline
          points={WORLD_ROUTE_POINTS.map((p) => `${p.x},${p.y}`).join(" ")}
          fill="none"
          stroke={COLORS.vermilionSoft}
          strokeWidth="1.5"
          strokeDasharray="4 3"
        />

        {WORLD_ROUTE_POINTS.map((p) => (
          <g key={p.key}>
            <circle cx={p.x} cy={p.y} r="4" fill={p.key === "changan" ? COLORS.vermilion : COLORS.paper} stroke={COLORS.ink} strokeWidth="1.4" />
            <text
              x={p.x}
              y={p.y + p.labelDy}
              textAnchor="middle"
              style={{ fontFamily: "'Noto Serif SC', serif", fontSize: 10, fontWeight: p.key === "changan" ? 700 : 400, fill: COLORS.inkSoft }}
            >
              {p.label}
            </text>
          </g>
        ))}
      </svg>
      <p style={{ fontSize: 10.5, color: COLORS.mist, marginTop: 8 }}>
        敦煌からカシュガルまでの中国国内区間は、下の詳細地図で紹介しています。
      </p>
    </div>
  );
}

function SilkRoadMap({ stops }) {
  return (
    <div style={{ backgroundColor: "#FBF8F0", border: "1px solid #DCD3B8", padding: 16, marginBottom: 28 }}>
      <p style={{ fontSize: 11.5, color: COLORS.inkSoft, marginBottom: 10 }}>
        実際の海岸線をもとにした中国の位置関係図です。敦煌で天山南路（北道）と崑崙山北路（南道）に分かれ、
        いずれもパミール高原を越えて中央アジアへと続きます。朱色の番号は下の一覧のオアシス都市、
        砂色の部分はタクラマカン砂漠、金色の破線は漢代以降「西域」と呼ばれた領域のおおよその目安です。
      </p>
      <svg viewBox="0 0 500 366" style={{ width: "100%", maxHeight: 420, display: "block", margin: "0 auto" }}>
        <path d={CHINA_OUTLINE} fill="#DCD3B8" stroke={COLORS.mist} strokeWidth="1.2" strokeLinejoin="round" />
        <path d={TAIWAN_OUTLINE} fill="#DCD3B8" stroke={COLORS.mist} strokeWidth="1.2" strokeLinejoin="round" />

        <path
          d={WESTERN_REGIONS_BOUNDARY}
          fill={COLORS.gold}
          fillOpacity="0.07"
          stroke={COLORS.gold}
          strokeWidth="1.2"
          strokeDasharray="6 4"
          strokeLinejoin="round"
        />
        <text
          x="93"
          y="100"
          textAnchor="middle"
          style={{ fontFamily: "'Noto Serif SC', serif", fontSize: 11, fontWeight: 700, fill: COLORS.gold, letterSpacing: "0.15em" }}
        >
          西域
        </text>

        <path d={TAKLAMAKAN_DESERT} fill="#D8B978" fillOpacity="0.6" stroke="#B99A4E" strokeWidth="1" strokeDasharray="1 2" strokeLinejoin="round" />
        <text
          x="95"
          y="154"
          textAnchor="middle"
          style={{ fontFamily: "'Noto Serif SC', serif", fontSize: 9, fill: "#7A5C22", opacity: 0.9 }}
        >
          タクラマカン砂漠
        </text>

        {REGION_LABELS.map((r, i) => (
          <text
            key={`region-${i}`}
            x={r.x + (r.dx || 0)}
            y={r.y + (r.dy || 0)}
            textAnchor={r.anchor}
            style={{ fontFamily: "'Noto Serif SC', serif", fontSize: 10.5, fill: COLORS.inkSoft, opacity: 0.85 }}
          >
            {r.label}
          </text>
        ))}

        <polyline points={toPoints(TRUNK_ROUTE)} fill="none" stroke={COLORS.vermilionSoft} strokeWidth="1.5" strokeDasharray="4 3" />
        <polyline points={toPoints(NORTH_ROUTE)} fill="none" stroke={COLORS.vermilionSoft} strokeWidth="1.5" strokeDasharray="4 3" />
        <polyline points={toPoints(SOUTH_ROUTE)} fill="none" stroke={COLORS.vermilionSoft} strokeWidth="1.5" strokeDasharray="4 3" />

        <circle cx={XIAN.x} cy={XIAN.y} r="4" fill={COLORS.paper} stroke={COLORS.ink} strokeWidth="1.4" />
        <text
          x={XIAN.x + 8}
          y={XIAN.y - 6}
          style={{ fontFamily: "'Noto Serif SC', serif", fontSize: 10.5, fill: COLORS.inkSoft }}
        >
          長安（起点）
        </text>

        {stops.map((stop, i) => (
          <g key={i}>
            <circle cx={stop.mapX} cy={stop.mapY} r="7.5" fill={COLORS.vermilion} stroke={COLORS.paper} strokeWidth="1.4" />
            <text
              x={stop.mapX}
              y={stop.mapY}
              textAnchor="middle"
              dominantBaseline="central"
              style={{ fontFamily: "'Noto Serif SC', serif", fontSize: 8.5, fontWeight: 700, fill: "#FBF8F0" }}
            >
              {i + 1}
            </text>
          </g>
        ))}
      </svg>
    </div>
  );
}

